from collections import deque,Counter
def transform(g):
    h,w=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    seen=[[False]*w for _ in range(h)]
    out=[r[:] for r in g]
    def comp(sr,sc):
        col=g[sr][sc]; q=deque([(sr,sc)]); cells=[]
        seen[sr][sc]=True
        while q:
            r,c=q.popleft(); cells.append((r,c))
            for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                nr,nc=r+dr,c+dc
                if 0<=nr<h and 0<=nc<w and not seen[nr][nc] and g[nr][nc]==col:
                    seen[nr][nc]=True; q.append((nr,nc))
        return cells
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bg and not seen[r][c]:
                cells=comp(r,c)
                rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                closed = len(cells)==(r1-r0+1)*(c1-c0+1)  # solid bbox => full rectangle border+interior
                if closed:
                    for rr in range(r0+1,r1):
                        for cc in range(c0+1,c1):
                            if out[rr][cc]==bg: out[rr][cc]=7
    return out
